        List<String> vals = new ArrayList<>(Arrays.asList("10", "20"));
        valuesField.set(opt, vals);
        // prepare options list and args list
        List<String> args = new ArrayList<>();
        List<Option> options = new ArrayList<>();
        options.add(opt);
        // use the private constructor CommandLine(List<String>, List<Option>, Consumer<Option>)
